CREATE TABLE _migration_0060_guard (valid INTEGER NOT NULL CHECK (valid = 1));
INSERT INTO _migration_0060_guard (valid)
SELECT CASE WHEN (SELECT COUNT(*) FROM network_stores) = 3
  AND (SELECT SUM(total_units) FROM network_stores) = 3511
  AND (SELECT COUNT(*) FROM network_inventory) = 790
  THEN 1 ELSE 0 END;
DROP TABLE _migration_0060_guard;
